CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TABLE IF NOT EXISTS workspaces(id uuid PRIMARY KEY, token_hash text UNIQUE NOT NULL, csrf text NOT NULL, admin boolean NOT NULL DEFAULT false, expires_at timestamptz NOT NULL DEFAULT now()+interval '48 hours');
CREATE TABLE IF NOT EXISTS services(id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces ON DELETE CASCADE,name text NOT NULL,duration integer NOT NULL CHECK(duration BETWEEN 15 AND 180 AND duration%15=0),price integer NOT NULL CHECK(price>=0),description text NOT NULL,active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS staff(id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces ON DELETE CASCADE,name text NOT NULL,bio text NOT NULL,active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS staff_services(staff_id uuid REFERENCES staff ON DELETE CASCADE,service_id uuid REFERENCES services ON DELETE CASCADE,PRIMARY KEY(staff_id,service_id));
CREATE TABLE IF NOT EXISTS working_hours(id uuid PRIMARY KEY,staff_id uuid NOT NULL REFERENCES staff ON DELETE CASCADE,weekday integer NOT NULL CHECK(weekday BETWEEN 1 AND 7),start_minute integer NOT NULL,end_minute integer NOT NULL,CHECK(start_minute>=0 AND end_minute<=1440 AND start_minute<end_minute));
CREATE TABLE IF NOT EXISTS blocked_times(id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces ON DELETE CASCADE,staff_id uuid NOT NULL REFERENCES staff ON DELETE CASCADE,starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,reason text NOT NULL,CHECK(ends_at>starts_at));
CREATE TABLE IF NOT EXISTS appointments(id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces ON DELETE CASCADE,reference text UNIQUE NOT NULL,manage_hash text UNIQUE NOT NULL,idempotency_key uuid NOT NULL,request_hash text NOT NULL,service_id uuid NOT NULL REFERENCES services,staff_id uuid NOT NULL REFERENCES staff,service_name text NOT NULL,staff_name text NOT NULL,duration integer NOT NULL,price integer NOT NULL,starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,name text NOT NULL,email text NOT NULL,phone text NOT NULL,note text NOT NULL DEFAULT '',status text NOT NULL DEFAULT 'booked' CHECK(status IN ('booked','confirmed','completed','cancelled','no-show')),version integer NOT NULL DEFAULT 1,reminder_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),CHECK(ends_at>starts_at),UNIQUE(workspace_id,idempotency_key),EXCLUDE USING gist(workspace_id WITH =,staff_id WITH =,tstzrange(starts_at,ends_at,'[)') WITH &&) WHERE(status IN ('booked','confirmed')));
CREATE TABLE IF NOT EXISTS appointment_events(id uuid PRIMARY KEY,appointment_id uuid NOT NULL REFERENCES appointments ON DELETE CASCADE,kind text NOT NULL,actor text NOT NULL,detail jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS notifications(id uuid PRIMARY KEY,appointment_id uuid NOT NULL REFERENCES appointments ON DELETE CASCADE,kind text NOT NULL,version integer NOT NULL,payload jsonb NOT NULL,state text NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','sending','delivered','review','cancelled','failed')),claim_hash text,attempts integer NOT NULL DEFAULT 0,next_attempt_at timestamptz NOT NULL DEFAULT now(),claimed_at timestamptz,delivered_at timestamptz,message_id text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(appointment_id,kind,version));
CREATE INDEX IF NOT EXISTS appointment_workspace_date ON appointments(workspace_id,starts_at);
ALTER TABLE appointments ADD COLUMN IF NOT EXISTS schedule_version integer NOT NULL DEFAULT 1;
CREATE INDEX IF NOT EXISTS reminder_due ON appointments(reminder_at) WHERE status IN ('booked','confirmed');
CREATE INDEX IF NOT EXISTS notification_due ON notifications(next_attempt_at) WHERE state='pending';
CREATE TABLE IF NOT EXISTS usage_limits(key text PRIMARY KEY,count integer NOT NULL,expires_at timestamptz NOT NULL);
